exercise.solution:
// 기본 인자 덕분에 오버로딩 세 개가 이 하나로 접힌다.
fun formatLog(message: String, level: String = "INFO", tag: String = "app"): String =
    "[$tag] $level $message"

// separator 가 vararg 뒤에 있으므로 호출부에서 이름으로만 넘길 수 있다.
fun joinAll(vararg parts: String, separator: String = " / "): String {
    var out = ""
    for ((i, p) in parts.withIndex()) {
        if (i > 0) out += separator     // 구분자는 앞에 — 뒤에 붙이면 끝에 남는다
        out += p
    }
    return out
}

// clean 은 report 밖에서는 의미가 없다. 지역 함수로 두면 클래스 API 가 깨끗해진다.
fun report(name: String, email: String): String {
    fun clean(s: String) = s.trim().lowercase()
    return "${clean(name)}<${clean(email)}>"
}

// Nothing 은 모든 타입의 하위 타입이라 ?: 오른쪽 어디에든 놓을 수 있다.
fun fail(reason: String): Nothing = throw IllegalArgumentException(reason)

fun port(raw: String?): Int = raw?.toIntOrNull() ?: fail("포트 파싱 실패: $raw")

// 누산기를 기본 인자로 둬서 덧셈을 호출 "안"으로 밀어 넣었다 — 그래서 꼬리 재귀가 된다.
tailrec fun digitSum(n: Int, acc: Int = 0): Int =
    if (n == 0) acc else digitSum(n / 10, acc + n % 10)

fun main() {
    println(formatLog("시작"))
    println(formatLog("응답 느림", level = "WARN"))
    println(formatLog("커넥션 끊김", tag = "db", level = "ERROR"))

    println(joinAll("a", "b", "c"))
    println(joinAll("x", "y", separator = "-"))
    println(joinAll(*arrayOf("p", "q", "r")))

    println(report("  Ada  ", "  ADA@Example.COM "))

    println(port("8080"))
    try {
        port("abc")
    } catch (e: IllegalArgumentException) {
        println(e.message)
    }

    println(digitSum(9875))
    println(digitSum(0))
}
